int xfs_attr_shortform_add(xfs_da_args_t *args) {
    int error;

    /* Trace the attribute addition operation */
    trace_xfs_attr_add(args);

    /* Check if the attribute already exists */
    if (args->op_flags & XFS_DA_OP_ADDNAME) {
        error = xfs_attr_lookup(args);
        if (error == 0) {
            if (args->op_flags & XFS_DA_OP_ATTR_REPLACE)
                return -EEXIST;
            if (args->op_flags & XFS_DA_OP_ATTR_CREATE)
                return -EEXIST;
            /* Attempt to remove the existing attribute */
            error = xfs_attr_shortform_remove(args);
            if (error)
                return error;
        } else if (error != -ENOENT) {
            return error;
        }
    }

    /* Check if the name or value length exceeds the maximum allowed size */
    if (args->valuelen > XFS_ATTR_MAX_SHORT_SIZE)
        return -EINVAL;
    if (args->namelen > XFS_ATTR_MAX_SHORT_NAME)
        return -EINVAL;

    /* Calculate the new size required for the attribute */
    int new_size = args->namelen + args->valuelen + XFS_ATTR_SF_HEADER_SIZE;

    /* Check if it can fit in the available space */
    if (new_size > XFS_ATTR_MAX_SHORT_SIZE)
        return -ENOSPC;

    /* Add the attribute */
    return xfs_attr_shortform_add_int(args);
}

int xfs_attr_add_shortform(xfs_da_args_t *args)
{
    int error;

    trace_xfs_attr_add(args->dp, args->name, args->val, args->namelen, args->valuelen);

    if (args->flags & ATTR_REPLACE) {
        if (!args->inleaf) {
            return -ENOATTR;
        }
    }

    if (args->flags & ATTR_CREATE) {
        if (args->inleaf) {
            return -EEXIST;
        }
    }

    if (args->inleaf) {
        error = xfs_attr_remove_leaf(args);
        if (error) {
            return error;
        }
    }

    if (args->namelen > XFS_ATTR_MAX_NAMELEN || args->valuelen > XFS_ATTR_MAX_VALLEN) {
        return -ENAMETOOLONG;
    }

    if (args->inleaf && args->leaf->hdr.count + 1 > XFS_ATTR_MAX_SHORT) {
        return -ENOSPC;
    }

    error = xfs_attr_add_leaf(args);
    if (error) {
        return error;
    }

    return 0;
}

#include <linux/xfs.h>
#include <linux/xfs_da_btree.h>
#include <linux/xfs_attr.h>

int xfs_attr_add_short(xfs_da_args_t *args)
{
    int error;

    /* Trace attribute addition operation */
    XFS_DA_OP_LOG(args, XFS_LOG_REG_DAS, XFS_DA_OP_ADD);

    /* Check if the attribute already exists */
    error = xfs_attr_lookup(args->dp, args->name, args->val, args->flags, args->hashval, NULL);
    if (error == 0) {
        /* Attribute already exists */
        if ((args->flags & ATTR_REPLACE) == 0) {
            /* ATTR_CREATE flag implies the attribute should not exist */
            if (args->flags & ATTR_CREATE)
                return -EEXIST;
        } else {
            /* Attempt to remove the existing attribute before adding the new one */
            error = xfs_attr_remove(args->dp, args->name, args->val, args->flags);
            if (error)
                return error;
        }
    } else if (error != -ENOATTR && error != -EEXIST) {
        return error;
    }

    /* Check if name or value length exceeds the maximum allowed size */
    if (args->namelen > XFS_ATTR_MAXNAMELEN || args->valuelen > XFS_ATTR_MAXVALUelen)
        return -ENAMETOOLONG;

    /* Calculate the size required for the new attribute */
    args->total_bytes = args->namelen + args->valuelen + sizeof(xfs_attr_leaf_entry_t);

    /* Check if the attribute can fit in available space */
    if (args->total_bytes > args->total_space)
        return -ENOSPC;

    /* Add the attribute */
    return xfs_attr_add_int(args);
}

int xfs_attr_shortform_add(xfs_da_args_t *args) {
    int error;

    trace_xfs_attr_add(args);

    if ((args->op_flags & XFS_ATTR_REPLACE) && !args->found) {
        return -EINVAL;
    }

    if ((args->op_flags & XFS_ATTR_CREATE) && args->found) {
        return -EEXIST;
    }

    if (args->found) {
        error = xfs_attr_remove(args);
        if (error) {
            return error;
        }
    }

    if (args->name.len > XFS_ATTR_MAX_NAMELEN || args->value.len > XFS_ATTR_MAX_VALUELEN) {
        return -ENAMETOOLONG;
    }

    args->total_size = args->name.len + args->value.len + sizeof(xfs_attr_leaf_entry_t) + 1;

    if (args->total_size > args->blksize) {
        return -ENOSPC;
    }

    return xfs_attr_leaf_add(args);
}

int xfs_attr_add_shortform(xfs_da_args_t *args) {
    int error;

    trace_xfs_attr_add(args->dp, args->name, args->val, args->namelen, args->valuelen, _RET_IP_);

    /* Check if attribute already exists */
    if (args->exist) {
        if (args->op_flags & XFS_ATTR_REPLACE) {
            if (args->exist->flags & XFS_ATTR_INCOMPLETE) {
                xfs_attr_unlink(args);
            } else {
                return -EEXIST;
            }
        } else if (args->op_flags & XFS_ATTR_CREATE) {
            return -EEXIST;
        }
    }

    /* Check name and value length against maximum allowed size */
    if (args->namelen > XFS_ATTR_MAX_NAMELEN || args->valuelen > XFS_ATTR_MAX_VALLEN) {
        return -ENAMETOOLONG;
    }

    /* Calculate the new size required for the attribute */
    args->total_len = args->namelen + args->valuelen + sizeof(xfs_attr_leaf_entry_t) +
                      sizeof(xfs_attr_shortform_t);

    /* Check if the new attribute can fit in the available space */
    if (args->total_len > XFS_ATTR_MAX_SHORTFORM_SIZE) {
        return -ENOSPC;
    }

    /* Add the attribute to the short-form attribute list */
    error = xfs_attr_leaf_add(args);
    if (error) {
        return error;
    }

    return 0;
}
